use crate::ciphers::lcg_stream::cipher::lcg_stream_encrypt;
use crate::ciphers::lcg_stream::keys::lcg_stream_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one encryption pass over `input_len` generated bytes.
pub fn lcg_stream_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let key = lcg_stream_default_key();
    let watch = Stopwatch::start();
    let sealed = lcg_stream_encrypt(&data, key);
    std::hint::black_box(sealed.len());
    watch.elapsed_ns()
}
